  "security.problems.ad_hardening.spn_users.action": "Задайте длинный случайный пароль служебной учётке вместе с владельцем службы.",
  "security.problems.ad_hardening.rc4.title": "Учётные записи с риском слабого шифрования Kerberos",
  "security.problems.ad_hardening.rc4.what": "Учётки пользователей со SPN, у которых включён RC4 и нет AES: {count}. Пустой атрибут и компьютеры не оцениваются.",
  "security.problems.ad_hardening.rc4.why": "Слабое шифрование билета службы облегчает подбор пароля (RC4).",
  "security.problems.ad_hardening.rc4.action": "Проверьте поддержку шифрования AES у службы перед отключением RC4.",
  "security.problems.ad_hardening.unconstrained.title": "Неограниченное делегирование вне контроллеров домена",
  "security.problems.ad_hardening.unconstrained.what": "Включён TRUSTED_FOR_DELEGATION у пользователей или компьютеров, не являющихся DC: {count}.",
  "security.problems.ad_hardening.unconstrained.why": "Взлом такой службы может открыть доступ от имени вошедшего администратора (делегирование).",
  "security.problems.ad_hardening.unconstrained.action": "Проверьте с владельцем службы необходимость неограниченного делегирования.",
  "security.problems.ad_hardening.constrained.title": "Проверить делегирование на чувствительные службы",
  "security.problems.ad_hardening.constrained.what": "Найдено учёток с ограниченным делегированием на чувствительные классы служб: {count}. Это сведения для проверки, а не подтверждённая уязвимость.",
  "security.problems.ad_hardening.constrained.why": "Взломанная служба может получить доступ к разрешённым ей файлам или базам (делегирование).",
  "security.problems.ad_hardening.constrained.action": "Проверьте с владельцем службы список разрешённых целей делегирования (msDS-AllowedToDelegateTo).",
  "security.problems.ad_hardening.laps.title": "Проверить развёртывание LAPS",
  "security.problems.ad_hardening.laps.what": "Компьютеров вне DC без схемы LAPS или без возвращённых метаданных ротации: {count}. Недоступные метаданные не доказывают отсутствие LAPS.",
  "security.problems.ad_hardening.laps.why": "Одинаковый пароль местного администратора облегчает доступ сразу к нескольким компьютерам.",
  "security.problems.ad_hardening.laps.action": "Проверьте применение политики смены пароля местного администратора (Windows LAPS).",
  "security.problems.ad_hardening.old_service_password.title": "Давно не менялись пароли служебных учёток",
  "security.problems.ad_hardening.old_service_password.what": "Учёток со SPN и паролем старше {threshold} дней: {count}. Управляемые MSA/gMSA исключены.",
  "security.problems.ad_hardening.old_service_password.why": "Давно не менявшийся пароль оставляет больше времени для подбора или использования утечки.",
  "security.problems.ad_hardening.old_service_password.action": "Согласуйте смену пароля с владельцем службы.",
  "security.problems.ad_hardening.privileged_nonexpiring.title": "Пароль администратора никогда не истекает",
  "security.problems.ad_hardening.privileged_nonexpiring.what": "Включённых привилегированных учёток с флагом «пароль никогда не истекает»: {count}.",
  "security.problems.ad_hardening.privileged_nonexpiring.why": "Украденный пароль администратора может оставаться пригодным долгое время.",
  "security.problems.ad_hardening.privileged_nonexpiring.action": "Проверьте с владельцем учётки порядок регулярной смены пароля.",
  "security.problems.ad_hardening.machine_account_quota.title": "Пользователи могут создавать учётные записи компьютеров",
  "security.problems.ad_hardening.machine_account_quota.what": "Домены с MachineAccountQuota выше нуля: {count}.",
  "security.problems.ad_hardening.machine_account_quota.why": "Пользователи домена могут создавать учётные записи компьютеров в пределах квоты.",
  "security.problems.ad_hardening.machine_account_quota.action": "Установите MachineAccountQuota равным нулю, если право добавлять компьютеры выдано отдельно.",
  "security.problems.ad_hardening.lockout_threshold.title": "Порог блокировки учётных записей отключён",
  "security.problems.ad_hardening.lockout_threshold.what": "Политики паролей без порога блокировки: {count}.",
  "security.problems.ad_hardening.lockout_threshold.why": "По этим политикам повторные попытки входа не блокируют учётную запись.",
  "security.problems.ad_hardening.lockout_threshold.action": "Задайте порог блокировки учётных записей в этих политиках.",
  "security.problems.ad_hardening.admin_group_size.title": "Слишком много участников административных групп",
  "security.problems.ad_hardening.admin_group_size.what": "Групп Domain Admins, Enterprise Admins или Administrators с числом уникальных участников больше {threshold}: {count}. Вложенные группы раскрываются, участник считается один раз.",
  "security.problems.ad_hardening.admin_group_size.why": "Каждая лишняя учётка администратора увеличивает риск потери контроля над доменом.",
  "security.problems.ad_hardening.admin_group_size.action": "Проверьте необходимость каждого участника группы администраторов.",
  "security.problems.ad_hardening.inactive_privileged.title": "Неиспользуемые включённые административные учётки",
  "security.problems.ad_hardening.inactive_privileged.what": "Включённых привилегированных учёток с последним доступным входом старше {threshold} дней: {count}. Если даты нет, проверка не выполняется.",
  "security.problems.ad_hardening.inactive_privileged.why": "Забытую учётку администратора проще использовать незаметно.",
  "security.problems.ad_hardening.inactive_privileged.action": "Подтвердите с владельцем учётки необходимость её административных прав.",
