  "security.problems.presentation.t109.ransom-precursor.title": "Обнаружена подготовка к шифрованию",
  "security.problems.presentation.t109.ransom-precursor.what": "Хост {host}. На хосте запущена команда удаления резервных копий, отключения восстановления или остановки резервного копирования.",
  "security.problems.presentation.t109.ransom-precursor.why": "Так часто начинают шифровальщики: восстановление уничтожают до шифрования.",
  "security.problems.presentation.t109.ransom-precursor.next": "Немедленно проверьте хост и инициатора команды. Если действие не согласовано, изолируйте хост, ограничьте учётку и защитите офлайн-копии.",
  "security.problems.presentation.t109.ransom-precursor.limitation": "Зафиксирована команда или скрипт; успешное удаление копий и шифрование этим не доказаны.",
  "security.problems.presentation.audit_category.8272": "Система",
