  "security.problems.presentation.audit_category.8280": "Вход учётной записи",
  "security.problems.presentation.audit_category.logon": "Вход",
  "security.problems.presentation.t109.security-log-cleared.title": "Журнал безопасности очищен",
  "security.problems.presentation.t109.security-log-cleared.what": "{actor} очистил журнал безопасности на {computer} в {time}.",
  "security.problems.presentation.t109.security-log-cleared.why": "Очистка может скрыть действия атакующего и лишить SLI наблюдения.",
  "security.problems.presentation.t109.security-log-cleared.next": "1) Уточните у {actor}, зачем это сделано. 2) Если никто не подтверждает — считайте компьютер взломанным: смените пароли администраторов и проверьте «Изменения в домене» за сутки до очистки.",
  "security.problems.presentation.t109.security-log-cleared.next_without_names": "1) Уточните у администраторов, зачем очистили журнал. 2) Если очистку никто не подтверждает, смените пароли администраторов и проверьте «Изменения в домене» за сутки до очистки.",
  "security.problems.presentation.t109.security-log-cleared.limitation": "Очистка подтверждена; намерения инициатора требуют проверки.",
  "security.problems.presentation.t109.audit-disabled.title": "На компьютере отключили аудит",
  "security.problems.presentation.t109.audit-disabled.what": "{actor} отключил аудит «{category}» на {computer} в {time}.",
  "security.problems.presentation.t109.audit-disabled.why": "Атакующий может отключать аудит перед кражей или шифрованием данных.",
  "security.problems.presentation.t109.audit-disabled.next": "1) Верните настройку: в SLI «Агенты» → компьютер → «Аудит». 2) Уточните у {actor} причину.",
  "security.problems.presentation.t109.audit-disabled.next_without_names": "Верните настройку аудита в карточке компьютера на странице «Агенты».",
  "security.problems.presentation.t109.audit-disabled.limitation": "Изменение аудита подтверждено; это также может быть согласованное обслуживание.",
  "security.problems.presentation.t109.agent-tamper.title": "Агент SLI остановлен или отключён",
  "security.problems.presentation.t109.agent-tamper.what": "Служба агента на {computer} остановлена в {time}, запуск изменил {actor}.",
  "security.problems.presentation.t109.agent-tamper.why": "Прекращение наблюдения может предшествовать быстрой атаке.",
  "security.problems.presentation.t109.agent-tamper.next": "1) Запустите службу `SLIAgentNet` на компьютере. 2) Если её останавливали не вы — проверьте «Изменения в домене» по {actor}.",
  "security.problems.presentation.t109.agent-tamper.next_without_names": "1) Запустите службу SLIAgentNet на компьютере. 2) Если остановку никто не планировал, проверьте «Изменения в домене».",
  "security.problems.presentation.t109.agent-tamper.limitation": "Команда удаления означает попытку. Событие 7045 подтверждает установку с отключённым запуском, а не удаление службы.",
  "security.problems.presentation.t109.agent-silenced.title": "SLI замолчал после опасного события",
  "security.problems.presentation.t109.agent-silenced.what": "Хост {host}. При свежем контакте агента доставка событий просрочена; перед тишиной были очистка журнала, ослабление аудита или подготовка к шифрованию.",
  "security.problems.presentation.t109.agent-silenced.why": "Наблюдение пропало в ходе подозрительной последовательности действий.",
  "security.problems.presentation.t109.agent-silenced.next": "Срочно проверьте хост через независимый канал, состояние служб и журналы. Защитите резервные копии; при подтверждении атаки изолируйте хост.",
  "security.problems.presentation.t109.agent-silenced.limitation": "Свежий контакт подтверждает доступность агента, но не исправность всего хоста. Обычная тишина C08/C10 не создаёт этот сигнал.",
  "security.problems.presentation.t109.file-ransom-fast.title": "Быстрые массовые изменения файлов",
  "security.problems.presentation.t109.file-ransom-fast.what": "Хост {host}. Подтверждённые записи или удаления превысили быстрый порог политики: по умолчанию 30 разных файлов за 30 секунд.",
  "security.problems.presentation.t109.file-ransom-fast.why": "Машинный темп изменений требует проверки до распространения шифрования.",
  "security.problems.presentation.t109.file-ransom-fast.next": "Проверьте учётку, процесс и файлы. При несогласованных изменениях изолируйте источник и временно ограничьте запись в общие папки.",
  "security.problems.presentation.t109.file-ransom-fast.limitation": "Шифрование не доказано. Обычный порог 100 файлов за 300 секунд продолжает работать отдельно.",
  "security.problems.presentation.t109.mass-file-read.title": "Массовое чтение файлов или проверка доступа к ним",
  "security.problems.presentation.t109.mass-file-read.what": "Хост {host}. Одна учётка достигла порога политики: по умолчанию 200 разных файлов или 10 разных шар за 5 минут.",
  "security.problems.presentation.t109.mass-file-read.why": "Массовый доступ может предшествовать выносу данных и вымогательству.",
  "security.problems.presentation.t109.mass-file-read.next": "Проверьте учётку и источник доступа, согласованность экспорта. При подозрении ограничьте учётку и проверьте исходящие передачи; согласованные бэкап-учётки исключайте политикой.",
  "security.problems.presentation.t109.mass-file-read.limitation": "4663 подтверждает обращение; 5145 подтверждает проверку доступа на чтение. Объём передачи и вынос данных не доказаны.",
