  "security.problems.presentation.privileged_group_why": "Так злоумышленник закрепляется в сети: учётка из этой группы может делать в домене всё. Если добавление не планировали — это может быть атака.",
  "security.problems.presentation.privileged_group_next": "Узнайте, кто и зачем добавил учётку. Если никто не планировал — сразу удалите её из группы, смените пароль этой учётки и того, кто её добавил.",
  "security.problems.presentation.scheduled_task_title": "На компьютере создана задача планировщика",
