  "security.problems.presentation.scheduled_task_why": "Задачи планировщика часто используют вирусы и взломщики, чтобы их программа запускалась снова после перезагрузки.",
  "security.problems.presentation.scheduled_task_next": "Откройте задачу на компьютере и посмотрите, какую программу она запускает. Если задачу никто не создавал — отключите её и проверьте компьютер антивирусом.",
