  "reports.v2.security.events.chains.limitations.persistence_observations": "История содержит наблюдения в выбранном окне, а не восстановленное состояние или доказательство закрепления. Предыдущее значение — только предыдущее наблюдение; при неоднозначном порядке оно неизвестно. Обновления ПО могут быть легитимными.",
  "reports.v2.security.events.chains.limitations.persistence_linking": "4697 и 7045 связаны только при точном совпадении DC, времени, имени, файла, RunAs и типа запуска и единственной паре. Связь не доказывает одну установку. Частота — число наблюдений объекта (точная пара считается один раз), а не число установок. Неизвестные объекты и события без текущей семантики не объединяются; имена инициаторов не доказывают идентичность.",
  "reports.v2.security.events.chains.limitations.persistence_coverage": "Полнота источников не подтверждена. Карточки относятся к отфильтрованному ограниченному срезу: новые объекты означают наблюдавшееся создание/установку в окне, редкие пути/action — значения с частотой не выше заданного порога (по умолчанию 1). Отсутствие событий не доказывает отсутствие изменений или исполнения. XML задач не исполняется; неизвестные action и RunAs не восстанавливаются.",
  "reports.v2.security.events.chains.limitations.persistence_truncated": "Достигнут лимит событий или строк. История и счётчики частичные; при лимите событий связь 4697/7045 отключена. Сузьте период.",
  "reports.v2.security.events.chains.metrics.persistence_services.label": "Службы с наблюдаемой установкой",
  "reports.v2.security.events.chains.metrics.persistence_tasks.label": "Задачи с наблюдаемым созданием",
