  "reports.v2.security.events.chains.limitations.revocation_candidate": "Это кандидаты, а не доказательство обхода отключения. Учитывайте репликацию, существующие токены и погрешность часов (задержка до 60 с отмечена отдельно). 4624 на DC не доказывает интерактивный вход человека; 6272 — решение NPS, а не VPN-сессия.",
  "reports.v2.security.events.chains.limitations.revocation_coverage": "Полнота источников не подтверждена. Сопоставление — только точный SID в одном домене и текущая семантика. Неизвестные идентичности и события без текущей семантики показаны отдельно без связи по имени. Отсутствие 4722 не доказывает отсутствие повторного включения.",
  "reports.v2.security.events.chains.limitations.revocation_window": "Период задаёт время отключения/удаления. Новая аутентификация ищется в выбранном окне после него; карточки относятся к отфильтрованному ограниченному срезу. Accounting показывает отдельно старые сессии, пересекающие момент отключения; время последнего наблюдения сессии может выходить за окно аутентификации. Источник продолжения — RADIUS Accounting; полнота сессии сохранена отдельно.",
  "reports.v2.security.events.chains.limitations.revocation_accounting": "Accounting недоступен, не содержит сопоставленных строк или не проверен без точных якорей. Отсутствие продолжавшихся VPN-сессий не установлено.",
  "reports.v2.security.events.chains.limitations.revocation_truncated": "Достигнут лимит событий, сессий или строк. Счётчики — нижняя граница прочитанного среза; сузьте период.",
  "reports.v2.security.events.chains.metrics.revocation_logons.label": "Аккаунты с последующей 4624 (кандидаты)",
