  "reports.v2.vpn.connections.limitations.windows_unavailable": "Факты аутентификации Windows недоступны: проверьте источник и окно не шире 90 дней. Отсутствие строк не означает отсутствия событий.",
  "reports.v2.vpn.connections.limitations.windows_heatmap_unavailable": "Тепловая карта недоступна: проверьте доступ, источник и окно не шире 90 дней. Отсутствие данных не означает отсутствия отказов.",
