  "reports.v2.security.events.chains.limitations.recurring_correlation": "Точный SID и близость времени связывают наблюдения, но не доказывают причину блокировки. События без SID не объединяются по имени; автоматическое снятие блокировки может не создавать 4767.",
  "reports.v2.security.events.chains.limitations.recurring_coverage": "Полнота источника не подтверждена. Отсутствие сопоставленных ошибок или разблокирования не доказывает их отсутствие. Используется только текущая версия семантики; недостающие факты не восстанавливаются из старых версий.",
  "reports.v2.security.events.chains.limitations.recurring_metrics": "Карточки относятся к аккаунтам, прошедшим фильтры, в ограниченном срезе событий. Источники — различные значения caller, IP и workstation по отдельности, а не число устройств.",
  "reports.v2.security.events.chains.limitations.recurring_truncated": "Достигнут лимит событий или аккаунтов. Счётчики событий — нижняя граница по прочитанному срезу; сузьте период. Строки за пределами лимита не показаны.",
